  grid_initializeTrackSizes(ctx, grid, "columns")
  grid_initializeTrackSizes(ctx, grid, "rows")
  val again: Boolean = grid_completeTrackSizing(ctx, grid, "columns", constraint, false)
  // ts: packages/layout/src/grid.ts:2523
  if ((again || jsSome(grid.items, fun(i: GridItemData): Boolean {
    return i.sizingDependsOnBlockSize
}))) {
    val more: Boolean = grid_completeTrackSizing(ctx, grid, "rows", constraint, (!again))
    // ts: packages/layout/src/grid.ts:2525
    if ((more || again)) {
      grid_initializeTrackSizes(ctx, grid, "columns")
      grid_completeTrackSizing(ctx, grid, "columns", constraint, false)
    }
  }
  val span: Double = grid_fullSpanSize(grid.columns)
  return (if ((span == grid_INDEFINITE)) units_ZERO else span)
}
